            OnityLinqFunc<TSource, int> selector, CancellationToken cancellationToken)
        {
            IOnityAsyncEnumerator<TSource> enumerator = OnityLinqCore.Acquire(source, cancellationToken);
            try
            {
                long count = 0;
                long sum = 0;
                while (await enumerator.MoveNextAsync())
                {
                    int value = await selector.Invoke(enumerator.Current, cancellationToken);
                    checked
                    {
                        sum += value;
